{
  "versao": "1-ia-sozinha",
  "anotacoes": [
    {
      "trecho_id": "STATUS_C.RESUMO",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "Posição após o comunicado de suprimentos sobre redutor e sensor.",
          "motivo": "premissa_alterada",
          "correto_seria": "A posição deve refletir somente a revisão do detalhamento CAD; o evento aplicado não altera as datas do redutor ou do sensor."
        },
        {
          "citacao": "O redutor passou para D24 e o sensor para D18.",
          "motivo": "valor_divergente",
          "correto_seria": "Redutor disponível em D20 e sensor em D16."
        },
        {
          "citacao": "D44",
          "motivo": "valor_divergente",
          "correto_seria": "A liberação de engenharia ocorre em D43."
        },
        {
          "citacao": "quatro dias depois da linha de base",
          "motivo": "valor_divergente",
          "correto_seria": "Três dias depois da linha de base D40."
        },
        {
          "citacao": "passando pelo redutor",
          "motivo": "premissa_alterada",
          "correto_seria": "O redutor não está no caminho crítico; o caminho crítico passa pela engenharia, compras e fabricação, montagem, teste de vida, documentação e liberação."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "STATUS_C.SUPRIMENTOS",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "em D24",
          "motivo": "valor_divergente",
          "correto_seria": "O redutor está disponível em D20."
