        {
          "citacao": "sem folga",
          "motivo": "valor_divergente",
          "correto_seria": "O redutor tem 3 dias de folga até o início da montagem em D23."
        },
        {
          "citacao": "em D18",
          "motivo": "valor_divergente",
          "correto_seria": "O sensor está disponível em D16."
        },
        {
          "citacao": "com folga de 6 dias",
          "motivo": "valor_divergente",
          "correto_seria": "O sensor tem 7 dias de folga até o início da montagem em D23."
        },
        {
          "citacao": "motor em D18 (folga de 6 dias)",
          "motivo": "valor_divergente",
          "correto_seria": "O motor está em D18, com folga de 5 dias."
        },
        {
          "citacao": "kit da MetalForm em D17 (folga de 7 dias)",
          "motivo": "valor_divergente",
          "correto_seria": "O kit da MetalForm está em D17, com folga de 6 dias."
        },
        {
          "citacao": "eletrônica da ElecBoard em D19 (folga de 5 dias)",
          "motivo": "valor_divergente",
          "correto_seria": "A eletrônica da ElecBoard está em D19, com folga de 4 dias."
        },
        {
          "citacao": "acoplamento a partir de D18 (folga de 6 dias)",
          "motivo": "valor_divergente",
          "correto_seria": "O acoplamento está disponível a partir de D18, com folga de 5 dias."
        },
        {
          "citacao": "terminando em D20",
          "motivo": "valor_divergente",
          "correto_seria": "Compras e fabricação terminam em D23."
        },
        {
          "citacao": "4 dias de folga",
          "motivo": "valor_divergente",
          "correto_seria": "Compras e fabricação têm folga zero, pois terminam quando começa a montagem em D23."
        }
      ],
      "observacao": ""
    },
    {
      "trecho_id": "STATUS_C.ENGENHARIA",
      "rotulo": "REVISAR",
      "informacoes": [
        {
          "citacao": "Sem alterações",
          "motivo": "premissa_alterada",
          "correto_seria": "O detalhamento CAD foi estendido em 3 dias e passou a emitir o desenho na revisão 2."
        },
        {
          "citacao": "detalhamento CAD de D5 a D10 (revisão 1)",
          "motivo": "valor_divergente",
          "correto_seria": "Detalhamento CAD de D5 a D13, com emissão do desenho na revisão 2."
